const labels = {highlights:'竞技高光',bloopers:'趣味回合',both:'竞技 + 趣味双榜',auto:'自动',rules:'本地规则（离线）',rallies:'完整回合',events:'事件理解',zh:'中文',en:'English',lively:'设计成片',classic:'经典简洁',custom:'自由搭配',required:'必须通过复核',off:'关闭',shared:'共享推理',independent:'独立推理',manifest:'回合清单',rank:'选球排名',replay:'慢回放',render:'成片渲染',verify:'完整性验证',fetch:'下载并校验','import-file':'导入本地文件',prepare:'准备请求（离线）',run:'执行',list:'列出模板',show:'查看模板',import:'导入模板',export:'导出模板',analytics:'动作分析',tracking:'球轨迹',player:'球员识别','frames-audio':'画面与同步音频',frames:'仅画面',needed:'按需',all:'全部',matchday:'赤线竞技',atelier:'纸上球场',sumi:'墨间回合',aurora:'极光棱镜',archive:'胶片纪事'};
const statusLabels = {queued:'排队中',running:'运行中',cancelling:'正在取消',cancelled:'已取消',succeeded:'已完成',failed:'失败',interrupted:'已中断'};
const S={data:null,jobs:[],media:{outputs:[],materials:[]},libraryKind:'outputs',librarySearch:'',libraryPage:0,route:'home',createMode:'run',createValues:{run:{ranker:'rules',template:'matchday'},match:{ranker:'rules',template:'matchday'}},tool:'infer',sub:'',toolValues:{},selectedJob:null,jobFilter:'all',picker:null,upload:null,template:null,templateValues:{},algorithm:null,cues:[],audioVideo:'',epoch:0};
const bytes=n=>n>=1024**3?(n/1024**3).toFixed(1)+' GB':n>=1024**2?(n/1024**2).toFixed(1)+' MB':n>=1024?(n/1024).toFixed(1)+' KB':n+' B';
